const mongoose = require('mongoose');

// One document per (article, device): lets us count each phone only once per article.
// `device` is a random anonymous id generated by the app — not personal data.
const articleViewSchema = new mongoose.Schema({
  article: { type: mongoose.Schema.Types.ObjectId, ref: 'Article', required: true },
  device: { type: String, required: true, maxlength: 64 },
}, { timestamps: { createdAt: true, updatedAt: false } });

articleViewSchema.index({ article: 1, device: 1 }, { unique: true });

module.exports = mongoose.model('ArticleView', articleViewSchema);
